import copy
import hashlib
import json
from pathlib import Path
root = Path.cwd()
local = root/'build/local-contracts-paired-20261002'
orchestration = json.loads((local/'orchestration.json').read_text())
assert orchestration['complete'] and orchestration['passed']
def digest(path): return hashlib.sha256(path.read_bytes()).hexdigest()
public = {'schema':'talven.local-contracts-evidence.v1', 'complete':True, 'passed':True, 'source_base_revision':'987e837', 'started_at':orchestration['started_at'], 'finished_at':orchestration['finished_at'], 'orders':orchestration['orders'], 'inputs':orchestration['inputs'], 'conditions':{'global':'existing default unit profiles', 'local':'explicit --local-contracts; same compiler, source root, cwd, toolchain and environment'}, 'reports':[], 'workload_texts':[], 'object_sets':{}, 'orchestration_sha256':digest(local/'orchestration.json'), 'orchestration_script':(root/'build/compare-local-contracts.py').read_text(), 'curation_script':Path(__file__).read_text(), 'unmeasured':['memory','cold OS caches','agent model/tokenizer/task cost','application readiness','state-preserving reload','other hosts/toolchains']}
for row in orchestration['reports']:
 directory = local/f"{row['experiment']}-pair-{row['pair']}-{row['condition']}"
 raw = json.loads((directory/'report.json').read_text())
 assert raw['complete'] and raw['passed'] and all(s['verified'] for s in raw['samples']) and len(raw['samples']) == 48
 r = copy.deepcopy(raw); r.pop('git_status',None)
 r['commands'] = [{k:v for k,v in c.items() if k not in ('argv','stdout','stderr')} | {stream:{k:v for k,v in c[stream].items() if k!='path'} for stream in ('stdout','stderr')} for c in raw['commands']]
 for sample in r['samples']:
  receipt = sample.get('receipt')
  if receipt and 'objects' in receipt:
   objects = receipt.pop('objects')
   key = hashlib.sha256(json.dumps(objects,sort_keys=True).encode()).hexdigest()
   public['object_sets'][key] = objects; receipt['object_set'] = key
 for session in r.get('sessions',[]):
  logs = directory/session.pop('path'); session.pop('argv')
  session['events'] = [json.loads(line) for line in (logs/'events.jsonl').read_text().splitlines()]
  for event in session['events']:
   if event['event'] == 'session_started': event.pop('source',None); event['cc'] = 'recorded trusted C driver'
  session['stdout_text'] = (logs/'stdout').read_text()
 if not any(w['experiment']==row['experiment'] for w in public['workload_texts']):
  for workload in raw['workloads']:
   for rev in workload['revisions']:
    d = directory/'workloads'/workload['id']/rev['id']
    public['workload_texts'].append({'experiment':row['experiment'],'workload':workload['id'],'revision':rev['id'],'source':(d/'source.tal').read_text(),'oracle':(d/'oracle.c').read_text() if (d/'oracle.c').exists() else None})
 public['reports'].append({'experiment':row['experiment'],'pair':row['pair'],'condition':row['condition'],'raw_report_sha256':digest(directory/'report.json'),'receipt':r})
metadata={k:v for k,v in public.items() if k not in ('curation_script','orchestration_script')}
assert all(prefix not in json.dumps(metadata) for prefix in ('/Users/','/private/','/var/folders/'))
destination = root/'experiments/results/local-contracts-macos-arm64-20261002.json'
destination.write_text(json.dumps(public,sort_keys=True,indent=2)+'\n')
print(destination.name,destination.stat().st_size,digest(destination))
print('wall',public['started_at'],public['finished_at'])
print('compiler',sorted({r['receipt']['compiler_hash'] for r in public['reports']}))
for experiment in ('objects','watch'):
 print(experiment)
 for workload in ('chain-32','chain-128','stores-128','borrowing'):
  for revision in ('initial','trivia','body','contract','invalid','repair'):
   cells=[];work=[]
   for condition in ('global','local'):
    samples=[s for row in public['reports'] if row['experiment']==experiment and row['condition']==condition for s in row['receipt']['samples'] if s['mode']=='units' and s['workload']==workload and s['revision']==revision]
    if not samples: continue
    cells.append(condition+': '+', '.join(f"{s.get('elapsed_ns',s.get('parent_to_receipt_ns'))/1e6:.3f}" for s in samples))
    work=[len(s['receipt']['compiled']) if s.get('receipt') else len(s.get('compiled_receipt',{}).get('compiled',[])) for s in samples]
   print(workload,revision,' | '.join(cells))

orchestration_script:
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
from datetime import datetime, timezone
root = Path.cwd()
result = root / 'build/local-contracts-paired-20261002'
result.mkdir()
files = sorted([*root.joinpath('talven').glob('*.py'), *[root / ('scripts/' + name) for name in ('measure-native-watch.py', 'measure-unit-rebuilds.py', 'measure-incremental.py', 'measure-tooling.py')], root / 'experiments/__init__.py', root / 'experiments/tooling_workloads.py', *root.joinpath('examples').glob('*.tal')])
def identity(path): return hashlib.sha256(path.read_bytes()).hexdigest()
report = {'schema':'talven.local-contracts-paired-local.v1', 'complete':False, 'passed':False, 'orders':[['global','local'],['local','global'],['global','local']], 'inputs':{str(p.relative_to(root)):identity(p) for p in files}, 'reports':[], 'started_at':datetime.now(timezone.utc).isoformat()}
def save(): (result/'orchestration.json').write_text(json.dumps(report, sort_keys=True, indent=2)+'\n')
save()
try:
 for experiment, script in [('objects','measure-unit-rebuilds.py'),('watch','measure-native-watch.py')]:
  for pair, order in enumerate(report['orders'], 1):
   for condition in order:
    out = result / f'{experiment}-pair-{pair}-{condition}'
    argv = [sys.executable, str(root/'scripts'/script), '--out', str(out), '--repetitions','1','--warmups','0','--timeout','60','--stable-toolchain','--expect-arch','aarch64','--environment-note','Apple M4 macOS ARM64; same checkout, compiler, cwd and inherited environment; only local-contracts flag differs; AB BA AB; strict C11 O2 no LTO; warm caches and background load uncontrolled; no competing agent tests/builds']
    if condition == 'local': argv.append('--local-contracts')
    row = {'experiment':experiment,'pair':pair,'condition':condition,'argv':argv,'returncode':None}
    report['reports'].append(row); save()
    with (result/(out.name+'.log')).open('wb') as log:
     row['returncode'] = subprocess.run(argv,cwd=root,env={**os.environ,'LC_ALL':'C','PYTHONHASHSEED':'0','PYTHONDONTWRITEBYTECODE':'1'},stdout=log,stderr=subprocess.STDOUT).returncode
    save(); assert row['returncode'] == 0, row
    data = json.loads((out/'report.json').read_text())
    assert data['passed'] and data['complete'] and len(data['samples']) == 48 and all(s['verified'] for s in data['samples'])
    row['report_sha256'] = identity(out/'report.json'); save()
    print(out.name,'accepted',flush=True)
  for pair in range(1,4):
   before = json.loads((result/f'{experiment}-pair-{pair}-global/report.json').read_text())
   after = json.loads((result/f'{experiment}-pair-{pair}-local/report.json').read_text())
   for key in ('python_executable','c_executable','c_version','c_target','flags','compiler_hash','inputs', 'effective_environment_hash' if experiment == 'objects' else 'child_environment_hash'):
    assert before[key] == after[key], key
   for bw, aw in zip(before['workloads'],after['workloads']):
    assert bw['id'] == aw['id'] and bw['criteria'] == aw['criteria']
    for br, ar in zip(bw['revisions'], aw['revisions']):
     assert all(br.get(key) == ar.get(key) for key in ('id','source','diagnostic','generated_c','oracle')), 'workload inputs differ'
   for b, a in zip(before['samples'],after['samples']):
    for key in ('phase','repetition','order','workload','revision','mode','source_hash','verified'):
     assert b.get(key) == a.get(key), key
 for path in files: assert identity(path) == report['inputs'][str(path.relative_to(root))]
 report.update(complete=True,passed=True)
finally:
 report['finished_at'] = datetime.now(timezone.utc).isoformat(); save()

